// ?update@Rva0025E0B0Module@@QAEXPAVObject@@@Z
// Retail 0x0025E0B0, 128 B. 24 non-reloc diffs: FX position lea EAX (ours ECX) and
// the status-mask zero register/store schedule (retail ECX, word0 stored last; ours EDX,
// word0 first). The mask is bit 3 (word 0): retail stores word1/word2 = 0 and word0 = 8.
// BitFlags/MAKE_OBJECT_STATUS_MASK spelling copied from matched ProneUpdate_startProneEffects.cpp.
// cl: /DNDEBUG /DWIN32 /MD /D_STLP_USE_STATIC_LIB
// stlport

#include <bitset>

typedef bool Bool;
typedef float Real;

template <int NUMBITS>
class BitFlags
{
public:
	enum _dummy_kInit { kInit };

	BitFlags(_dummy_kInit, int idx1)
	{
		m_bits.set(idx1);
	}

	BitFlags() { }

	void set(int idx) { m_bits.set(idx); }

private:
	_STL::bitset<NUMBITS> m_bits;
};

typedef BitFlags<86> ObjectStatusMaskType;

#define MAKE_OBJECT_STATUS_MASK(k) ObjectStatusMaskType(ObjectStatusMaskType::kInit, (k))

struct Coord3D
{
	Real x, y, z;
};

class Matrix3D;

class FXList
{
public:
	Bool bfmeIsBlocked();
	void doFXPos(const Coord3D *primary, const Matrix3D *primaryMtx = 0,
		Real primarySpeed = 0.0f, const Coord3D *secondary = 0) const;
};

class Object
{
public:
	const Coord3D *getPosition() const { return &m_pos; }
	void setStatus(const ObjectStatusMaskType &status, Bool set);

private:
	unsigned char m_unmodelled00[0x38];
	Coord3D m_pos;
};

class Rva0025DF30GiveUpgradeUpdate
{
public:
	void update();
};

struct Rva0025E0B0ModuleData
{
	unsigned char m_unmodelled[0x264];
	FXList *m_fxList;
};

class Rva0025E0B0Module
{
public:
	void update(Object *object);

private:
	unsigned char m_unmodelled00[4];
	Rva0025E0B0ModuleData *m_moduleData;
	unsigned char m_unmodelled08[0xe0];
	Bool m_flagE8;
	Bool m_flagE9;
	unsigned char m_unmodelledEA[2];
	Real m_valueEC;
};

void Rva0025E0B0Module::update(Object *object)
{
	if (object == 0)
		return;
	reinterpret_cast<Rva0025DF30GiveUpgradeUpdate *>(this)->update();
	m_flagE9 = false;
	FXList *fxList = m_moduleData->m_fxList;
	if (fxList != 0 && !fxList->bfmeIsBlocked())
		fxList->doFXPos(object->getPosition());
	object->setStatus(MAKE_OBJECT_STATUS_MASK(3), true);
	m_flagE8 = true;
	m_valueEC = 1.0f;
}
